import os
import subprocess
import re
import zipfile
import xml.etree.ElementTree as ET

source_dir = '/root/papers/all/'
target_base = '/root/papers/'

# Ensure target directories exist
for folder in ['LLM', 'trapped_ion_and_qc', 'black_hole', 'DNA', 'music_history']:
    os.makedirs(os.path.join(target_base, folder), exist_ok=True)

keywords = {
    'LLM': [r'\bllm\b', r'large language model', r'transformer', r'\bgpt\b', r'\bnlp\b', r'pre-training', r'in-context learning'],
    'trapped_ion_and_qc': [r'trapped[ -]ion', r'quantum computing', r'\bqubit\b', r'ion trap', r'quantum gate', r'quantum state'],
    'black_hole': [r'black hole', r'event horizon', r'general relativity', r'hawking radiation', r'schwarzschild', r'gravitational wave'],
    'DNA': [r'\bdna\b', r'\brna\b', r'genome', r'genomics', r'\bgenetics\b', r'nucleotide', r'double helix', r'chromosome']
}

def get_text_from_docx(p):
    try:
        with zipfile.ZipFile(p) as z:
            xml_content = z.read('word/document.xml')
            tree = ET.fromstring(xml_content)
            return "".join(tree.itertext())
    except Exception as e:
        print(f"Error reading docx {p}: {e}")
        return ""

def get_text_from_pptx(p):
    text = []
    try:
        with zipfile.ZipFile(p) as z:
            for name in z.namelist():
                if name.startswith('ppt/slides/slide') and name.endswith('.xml'):
                    xml_content = z.read(name)
                    tree = ET.fromstring(xml_content)
                    text.append("".join(tree.itertext()))
    except Exception as e:
        print(f"Error reading pptx {p}: {e}")
    return " ".join(text)

files = os.listdir(source_dir)
files.sort()

for filename in files:
    filepath = os.path.join(source_dir, filename)
    if not os.path.isfile(filepath): continue

    content = ""
    if filename.endswith('.pdf'):
        try:
            content = subprocess.check_output(['pdftotext', '-l', '2', filepath, '-'], stderr=subprocess.STDOUT).decode('utf-8', errors='ignore').lower()
        except: pass
    elif filename.endswith('.docx'):
        content = get_text_from_docx(filepath).lower()
    elif filename.endswith('.pptx'):
        content = get_text_from_pptx(filepath).lower()
    else:
        try:
            content = subprocess.check_output(['strings', filepath]).decode('utf-8', errors='ignore').lower()
        except: pass

    assigned = False
    # Check 1-4
    for category in ['LLM', 'trapped_ion_and_qc', 'black_hole', 'DNA']:
        if any(re.search(kw, content) for kw in keywords[category]):
            dest = os.path.join(target_base, category, filename)
            os.rename(filepath, dest)
            print(f"Moved {filename} to {category}")
            assigned = True
            break

    if not assigned:
        dest = os.path.join(target_base, 'music_history', filename)
        os.rename(filepath, dest)
        print(f"Moved {filename} to music_history")

